
INSERT INTO service_translations (service_id, language_id, title, short_description, long_description, seo_title, meta_description) VALUES
('20ec9f32-9817-4ffd-aef4-b48230111d66', 1, 'Digital Marketing Agency', 'Full-service digital marketing agency delivering data-driven strategies across SEO, paid media, social, and content to accelerate your growth online.', '<h2>Why Choose Advisable as Your Digital Marketing Agency</h2><p>At <strong>Advisable</strong>, we combine deep industry expertise with cutting-edge technology to deliver digital marketing agency services that drive measurable business results. Our team of specialists works as an extension of your organization, crafting data-driven strategies tailored to your unique goals and market position.</p><h3>Our Digital Marketing Agency Services</h3><ul><li><strong>Strategic Planning & Audit</strong> — Comprehensive analysis of your current digital presence, competitive landscape, and growth opportunities.</li><li><strong>Campaign Execution & Management</strong> — Expert implementation and ongoing optimization across all channels.</li><li><strong>Performance Tracking & Analytics</strong> — Real-time dashboards, attribution modeling, and actionable insights.</li><li><strong>Creative & Content Production</strong> — High-quality assets designed to engage and convert.</li><li><strong>Technology & Automation</strong> — AI and marketing automation to scale efficiently.</li></ul><h3>What Sets Our Digital Marketing Agency Apart</h3><p>We are a <strong>Google Premier Partner</strong> and <strong>Meta Business Partner</strong>, giving you access to beta features and advanced tools.</p><h3>Explore Our Related Services</h3><ul><li><a href="/digital-agency/marketing-growth">Marketing & Growth Services →</a></li><li><a href="/digital-agency/performance-marketing">Performance Marketing →</a></li><li><a href="/contact">Get a free strategy consultation →</a></li></ul>', 'Digital Marketing Agency | Advisable', 'Expert digital marketing agency in Greece. SEO, PPC, social media & content strategies that drive measurable growth. Get a free consultation today.'),

('6bee1e67-d381-47fc-befb-e15f47878906', 1, 'Content Marketing Agency', 'Strategic content marketing agency creating high-impact blogs, whitepapers, and video content that builds authority and drives organic traffic.', '<h2>Why Choose Advisable as Your Content Marketing Agency</h2><p>At <strong>Advisable</strong>, we create content strategies that build authority, drive organic traffic, and convert readers into customers. Our content marketing team combines SEO expertise with compelling storytelling.</p><h3>Our Content Marketing Services</h3><ul><li><strong>Content Strategy & Planning</strong> — Editorial calendars, topic research, and content audits aligned to your business goals.</li><li><strong>Blog & Article Production</strong> — SEO-optimized long-form content that ranks and engages.</li><li><strong>Video & Multimedia Content</strong> — Engaging formats for social, web, and advertising.</li><li><strong>Content Distribution</strong> — Multi-channel amplification strategies.</li></ul><h3>Explore Related Services</h3><ul><li><a href="/digital-agency/content-creation">Content Creation →</a></li><li><a href="/digital-agency/seo-ai-visibility">SEO & AI Visibility →</a></li><li><a href="/contact">Free consultation →</a></li></ul>', 'Content Marketing Agency | Advisable', 'Award-winning content marketing agency. We create SEO-optimized content strategies that build brand authority and generate qualified leads.'),

('ed6e8c7e-8c77-4343-b30e-8d9372d3f812', 1, 'Branding Agency', 'Expert branding agency crafting distinctive brand identities, visual systems, and brand strategies that differentiate your business.', '<h2>Why Choose Advisable as Your Branding Agency</h2><p><strong>Advisable</strong> helps businesses build memorable brands that stand out. From brand strategy to visual identity, we create cohesive brand experiences across every touchpoint.</p><h3>Our Branding Services</h3><ul><li><strong>Brand Strategy & Positioning</strong> — Market research, competitive analysis, and brand architecture.</li><li><strong>Visual Identity Design</strong> — Logo, color palette, typography, and design systems.</li><li><strong>Brand Guidelines</strong> — Comprehensive style guides for consistency.</li><li><strong>Brand Messaging</strong> — Voice, tone, and messaging frameworks.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/brand-strategy">Brand Strategy →</a></li><li><a href="/digital-agency/ui-ux-design">UI/UX Design →</a></li><li><a href="/contact">Start your branding project →</a></li></ul>', 'Branding Agency | Advisable', 'Professional branding agency in Greece. Brand strategy, visual identity & positioning that makes your business unforgettable. Book a discovery call.'),

('3cb33edf-89e8-441b-9789-0792fb3754f2', 1, 'Video Production Agency', 'Professional video production agency creating compelling brand videos, ads, and social content that captures attention and drives conversions.', '<h2>Why Choose Advisable as Your Video Production Agency</h2><p>Our <strong>video production team</strong> creates scroll-stopping content for brands that want to stand out. From concept to final cut, we handle every aspect of production.</p><h3>Our Video Services</h3><ul><li><strong>Brand & Corporate Videos</strong> — Company stories, culture videos, and product showcases.</li><li><strong>Social Media Content</strong> — Short-form video optimized for each platform.</li><li><strong>Ad Creative Production</strong> — High-converting video ads for Meta, YouTube, and TikTok.</li><li><strong>AI-Powered Video</strong> — Leveraging AI tools for efficient production at scale.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/ai-video-creation">AI Video Creation →</a></li><li><a href="/digital-agency/ai-creative-studio">AI Creative Studio →</a></li><li><a href="/contact">Request a quote →</a></li></ul>', 'Video Production Agency | Advisable', 'Creative video production agency. From concept to delivery — brand videos, ads & social content that engage and convert. Request a quote.'),

('73b9df14-e062-4021-a454-88fd3e6378a4', 1, 'Influencer Marketing Agency', 'Data-driven influencer marketing agency connecting brands with the right creators to amplify reach and drive measurable ROI.', '<h2>Why Choose Advisable as Your Influencer Marketing Agency</h2><p>We connect brands with <strong>authentic creators</strong> who resonate with your target audience. Our data-driven approach ensures every partnership delivers measurable results.</p><h3>Our Influencer Marketing Services</h3><ul><li><strong>Influencer Discovery & Vetting</strong> — AI-powered matching with audience-verified creators.</li><li><strong>Campaign Management</strong> — End-to-end coordination from briefing to reporting.</li><li><strong>Content Collaboration</strong> — Co-created content that feels authentic.</li><li><strong>Performance Analytics</strong> — ROI tracking and attribution.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/social-media-management">Social Media Management →</a></li><li><a href="/digital-agency/content-creation">Content Creation →</a></li><li><a href="/contact">Plan your campaign →</a></li></ul>', 'Influencer Marketing Agency | Advisable', 'Results-driven influencer marketing agency. We connect your brand with the right creators for authentic campaigns that deliver ROI.'),

('ef7f7c95-6b2f-481b-8b51-c168451ad5c6', 1, 'CRO Agency', 'Conversion rate optimization agency using A/B testing, UX analysis, and data-driven insights to turn more visitors into customers.', '<h2>Why Choose Advisable as Your CRO Agency</h2><p>Our <strong>CRO specialists</strong> identify friction points in your conversion funnel and implement data-backed changes that increase revenue without increasing ad spend.</p><h3>Our CRO Services</h3><ul><li><strong>Conversion Audit</strong> — Full funnel analysis identifying drop-off points and opportunities.</li><li><strong>A/B & Multivariate Testing</strong> — Rigorous experimentation frameworks.</li><li><strong>UX Optimization</strong> — User research, heatmaps, and session recordings.</li><li><strong>Landing Page Optimization</strong> — High-converting page design and copy.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/conversion-revenue-optimization">Conversion & Revenue Optimization →</a></li><li><a href="/digital-agency/tracking-attribution">Tracking & Attribution →</a></li><li><a href="/contact">Get a free CRO audit →</a></li></ul>', 'CRO Agency — Conversion Rate Optimization | Advisable', 'Expert CRO agency. A/B testing, UX optimization & data-driven strategies that increase your conversion rates and revenue. Free audit available.'),

('7dd3032c-6a14-4f89-bc96-52ac534fd969', 1, 'UX/UI Design Agency', 'Human-centered UX/UI design agency creating intuitive interfaces and digital experiences that delight users and drive business results.', '<h2>Why Choose Advisable as Your UX/UI Design Agency</h2><p>We design <strong>digital experiences</strong> that users love and businesses profit from. Our human-centered design process ensures every interface is intuitive, accessible, and conversion-optimized.</p><h3>Our UX/UI Design Services</h3><ul><li><strong>User Research & Testing</strong> — Interviews, surveys, and usability testing.</li><li><strong>Wireframing & Prototyping</strong> — Interactive prototypes for validation.</li><li><strong>Visual Design & Design Systems</strong> — Scalable component libraries.</li><li><strong>Responsive & Mobile Design</strong> — Seamless experiences across devices.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/ui-ux-design">UI/UX Design →</a></li><li><a href="/digital-agency/web-development">Web Development →</a></li><li><a href="/contact">Start your design project →</a></li></ul>', 'UX/UI Design Agency | Advisable', 'Expert UX/UI design agency. User research, wireframing & interface design that creates seamless digital experiences. Start your project today.'),

('b471b215-d53d-4d3b-8c2a-43767e4ded3a', 1, 'Mobile App Development Agency', 'Full-cycle mobile app development agency building native and cross-platform iOS and Android applications.', '<h2>Why Choose Advisable as Your Mobile App Development Agency</h2><p>From concept to App Store, our <strong>mobile development team</strong> builds performant, scalable apps using modern tech stacks including React Native, Flutter, and native Swift/Kotlin.</p><h3>Our Mobile App Services</h3><ul><li><strong>iOS & Android Development</strong> — Native and cross-platform solutions.</li><li><strong>App Strategy & UX</strong> — User journey mapping and prototyping.</li><li><strong>Backend & API Development</strong> — Scalable cloud infrastructure.</li><li><strong>App Store Optimization</strong> — ASO for visibility and downloads.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/mobile-app-development">Mobile App Development →</a></li><li><a href="/digital-agency/ai-web-app-development">AI Web App Development →</a></li><li><a href="/contact">Discuss your app idea →</a></li></ul>', 'Mobile App Development Agency | Advisable', 'Leading mobile app development agency. iOS, Android & cross-platform apps built with modern tech stacks. From concept to App Store launch.'),

('c4cfce55-1324-48c8-8f4a-34a592c0fe8b', 1, 'B2B Marketing Agency', 'Specialized B2B marketing agency helping technology and enterprise companies generate qualified leads and accelerate pipeline growth.', '<h2>Why Choose Advisable as Your B2B Marketing Agency</h2><p>We understand the <strong>complex B2B buying journey</strong>. Our strategies are built for longer sales cycles, multiple stakeholders, and high-value deals.</p><h3>Our B2B Marketing Services</h3><ul><li><strong>Account-Based Marketing (ABM)</strong> — Targeted campaigns for high-value accounts.</li><li><strong>Demand Generation</strong> — Content and campaigns that fill your pipeline.</li><li><strong>LinkedIn & Paid Channels</strong> — B2B-optimized advertising strategies.</li><li><strong>Marketing & Sales Alignment</strong> — CRM integration and lead scoring.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/marketing-growth">Marketing & Growth →</a></li><li><a href="/digital-agency/google-ads-campaigns">Google Ads Campaigns →</a></li><li><a href="/contact">Talk to our B2B experts →</a></li></ul>', 'B2B Marketing Agency | Advisable', 'Specialized B2B marketing agency. Lead generation, ABM & demand gen strategies that fill your pipeline with qualified prospects.'),

('e15ebc03-5392-44b8-9ae3-5504ce947d2f', 1, 'SaaS Marketing Agency', 'Growth-focused SaaS marketing agency driving user acquisition, reducing churn, and scaling ARR through proven strategies.', '<h2>Why Choose Advisable as Your SaaS Marketing Agency</h2><p>We specialize in <strong>SaaS growth</strong> — from product-led growth strategies to demand generation that scales your ARR predictably.</p><h3>Our SaaS Marketing Services</h3><ul><li><strong>Product-Led Growth (PLG)</strong> — Optimize activation, retention, and expansion.</li><li><strong>Demand Generation</strong> — Multi-channel campaigns driving qualified trials and demos.</li><li><strong>Content & SEO</strong> — Thought leadership that ranks and converts.</li><li><strong>Churn Reduction</strong> — Data-driven retention strategies.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/marketing-growth">Marketing & Growth →</a></li><li><a href="/digital-agency/performance-marketing">Performance Marketing →</a></li><li><a href="/contact">Talk to our SaaS experts →</a></li></ul>', 'SaaS Marketing Agency | Advisable', 'SaaS marketing agency driving growth. User acquisition, PLG strategies & demand generation that scale your ARR. Talk to our SaaS experts.'),

('5175aa21-dabf-47b1-9723-90c17173728f', 1, 'Lead Generation Agency', 'Results-driven lead generation agency using multi-channel strategies to fill your sales pipeline with qualified prospects.', '<h2>Why Choose Advisable as Your Lead Generation Agency</h2><p>We build <strong>predictable lead generation engines</strong> using a mix of paid, organic, and outbound channels tailored to your ideal customer profile.</p><h3>Our Lead Generation Services</h3><ul><li><strong>Paid Lead Gen</strong> — Google Ads, Meta, and LinkedIn campaigns.</li><li><strong>SEO & Content</strong> — Organic lead magnets and conversion funnels.</li><li><strong>Email & Automation</strong> — Nurture sequences that convert.</li><li><strong>Landing Pages & CRO</strong> — High-converting lead capture experiences.</li></ul><h3>Related Services</h3><ul><li><a href="/digital-agency/paid-growth-systems">Paid Growth Systems →</a></li><li><a href="/digital-agency/email-marketing">Email Marketing →</a></li><li><a href="/contact">Start generating leads →</a></li></ul>', 'Lead Generation Agency | Advisable', 'Expert lead generation agency. Multi-channel strategies that deliver qualified leads and fill your sales pipeline. Get started today.');
